pub use classical_channel::ClassicalChannel;

/// Represents a quantum key pair generated by QKD
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KeyPair {
    pub alice_key: Vec<u8>,
    pub bob_key: Vec<u8>,
    pub key_length: usize,
    pub error_rate: f64,
    pub privacy_amplified: bool,
}

/// QKD Protocol trait that all QKD implementations must implement
#[async_trait::async_trait]
pub trait QKDProtocol {
    async fn generate_keys(&mut self) -> QTLSResult<KeyPair>;
    async fn estimate_error_rate(&self) -> QTLSResult<f64>;
    async fn privacy_amplification(&mut self, key: &[u8]) -> QTLSResult<Vec<u8>>;
    fn get_protocol_name(&self) -> &'static str;
}

/// Main QKD implementation that can switch between different protocols
pub struct QKDProtocolImpl {
    config: QTLSConfig,
    quantum_channel: Arc<Mutex<QuantumChannel>>,
    classical_channel: Arc<Mutex<ClassicalChannel>>,
    protocol: Box<dyn QKDProtocol + Send + Sync>,
}

impl QKDProtocolImpl {
    pub fn new(config: QTLSConfig) -> QTLSResult<Self> {
        let quantum_channel = Arc::new(Mutex::new(QuantumChannel::new()));
        let classical_channel = Arc::new(Mutex::new(ClassicalChannel::new()));
        
        let protocol: Box<dyn QKDProtocol + Send + Sync> = match config.qkd_protocol.protocol_type {
            crate::QKDProtocolType::BB84 => Box::new(BB84Protocol::new(
                config.clone(),
                quantum_channel.clone(),
                classical_channel.clone(),
            )),
            crate::QKDProtocolType::E91 => Box::new(E91Protocol::new(
                config.clone(),
                quantum_channel.clone(),
                classical_channel.clone(),
            )),
        };

        Ok(Self {
            config,
            quantum_channel,
            classical_channel,
            protocol,
        })
    }

    pub async fn generate_keys(&mut self) -> QTLSResult<KeyPair> {
        log::info!("Starting QKD key generation with {}", self.protocol.get_protocol_name());
        
        let mut key_pair = self.protocol.generate_keys().await?;
        
        // Apply privacy amplification if configured
        if self.config.qkd_protocol.privacy_amplification_rounds > 0 {
            key_pair.alice_key = self.protocol.privacy_amplification(&key_pair.alice_key).await?;
            key_pair.bob_key = self.protocol.privacy_amplification(&key_pair.bob_key).await?;
            key_pair.privacy_amplified = true;
        }
        
        log::info!("QKD key generation completed. Key length: {}", key_pair.key_length);
        Ok(key_pair)
    }

    pub async fn estimate_error_rate(&self) -> QTLSResult<f64> {
        self.protocol.estimate_error_rate().await
    }

    pub fn get_config(&self) -> &QTLSConfig {
        &self.config
    }
}

/// Quantum state representation
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum QuantumState {
    Zero,
    One,
    Plus,
    Minus,
}

impl QuantumState {
    pub fn to_basis(&self) -> Basis {
        match self {
            QuantumState::Zero | QuantumState::One => Basis::Computational,
            QuantumState::Plus | QuantumState::Minus => Basis::Hadamard,
        }
    }
    
    pub fn to_bit(&self) -> Option<u8> {
        match self {
            QuantumState::Zero | QuantumState::Plus => Some(0),
            QuantumState::One | QuantumState::Minus => Some(1),
        }
    }
}

/// Measurement basis
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Basis {
    Computational, // Z-basis: |0⟩, |1⟩
    Hadamard,      // X-basis: |+⟩, |-⟩
}

impl Basis {
    pub fn random() -> Self {
        if rand::random::<bool>() {
            Basis::Computational
        } else {
            Basis::Hadamard
        }
    }
}

/// Qubit measurement result
#[derive(Debug, Clone)]
pub struct MeasurementResult {
    pub basis: Basis,
    pub bit_value: u8,
    pub timestamp: std::time::Instant,
} 